# M112-B8I-04: source-only guarded patch. Does not access databases.
$ErrorActionPreference = 'Stop'
Set-Location 'G:\footwear-omnichannel'
$root = (Get-Location).Path
$utf8 = New-Object System.Text.UTF8Encoding($false)
$changes = @()

$changes += @{ Path = 'apps\api\src\pos.ts'; Old = ''; New = '' }
$changes += @{ Path = 'apps\api\src\cash-reconciliation.ts'; Old = ''; New = '' }
$changes += @{ Path = 'apps\api\src\finance-controls.ts'; Old = ''; New = '' }

# Validate all anchors before modifying any file.
$prepared = @()
foreach ($change in $changes) {
    $path = Join-Path $root $change.Path
    if (-not (Test-Path $path)) { throw "Missing source: $path" }
    $content = [System.IO.File]::ReadAllText($path)
    $normalized = $content.Replace("`r`n", "`n")
    $old = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($change.Old))
    $new = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($change.New))
    if (-not $normalized.Contains($old)) { throw "Source mismatch: $path. No changes made." }
    if ($normalized.IndexOf($old) -ne $normalized.LastIndexOf($old)) { throw "Ambiguous anchor: $path" }
    $newline = if ($content.Contains("`r`n")) { "`r`n" } else { "`n" }
    $updated = $normalized.Replace($old, $new.TrimEnd("`n")).Replace("`n", $newline)
    $prepared += @{ Path=$path; Original=$content; Updated=$updated }
}
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupDir = Join-Path $root "security-checks\M112\backups\M112B8I_04_$stamp"
New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
foreach ($item in $prepared) {
    Copy-Item -LiteralPath $item.Path -Destination (Join-Path $backupDir ([System.IO.Path]::GetFileName($item.Path))) -ErrorAction Stop
}
foreach ($item in $prepared) {
    [System.IO.File]::WriteAllText($item.Path, $item.Updated, $utf8)
    Write-Host "PATCHED $($item.Path)" -ForegroundColor Green
}
Write-Host "Backups: $backupDir" -ForegroundColor Cyan
Write-Host 'No database commands were executed.' -ForegroundColor Green
